TARGET_PC_KEY = ""

def run_launcher():
    global TARGET_PC_KEY
    
    # 🚀 1. 현재 실행된 파일 이름(예: 미니1.exe, mini2.py 등)을 소문자로 가져옵니다.
    exe_name = os.path.basename(sys.argv[0]).lower()
    
    # 🚀 2. 파일 이름에 포함된 단어를 스캔하여 자동으로 호기 배정! (한글, 영어 모두 지원)
    if "미니1" in exe_name or "mini1" in exe_name:
        TARGET_PC_KEY = "미니1"
    elif "미니2" in exe_name or "mini2" in exe_name:
        TARGET_PC_KEY = "미니2"
    elif "미니3" in exe_name or "mini3" in exe_name:
        TARGET_PC_KEY = "미니3"
    elif "미니4" in exe_name or "mini4" in exe_name: # 🚀 미니4 추가!
        TARGET_PC_KEY = "미니4"
        
    # 🚀 3. 정체성을 찾았다면? 런처 띄울 필요 없이 0.1초 만에 프리패스 통과!
    if TARGET_PC_KEY:
        print(f"🚀 [자동 인식] 파일명({exe_name})에서 '{TARGET_PC_KEY}'(을)를 발견했습니다! 런처를 생략하고 쾌속 진입합니다.")
        return

    # 💡 만약 파일 이름이 평범한 'macro.exe' 거나 파이썬 에디터에서 실행했다면 예비용 런처를 띄워줍니다.
    launch_root = tk.Tk()
    launch_root.title("다클라 독립 런처")
    
    window_width, window_height = 300, 150
    screen_width = launch_root.winfo_screenwidth()
    screen_height = launch_root.winfo_screenheight()
    x = int((screen_width / 2) - (window_width / 2))
    y = int((screen_height / 2) - (window_height / 2))
    launch_root.geometry(f"{window_width}x{window_height}+{x}+{y}")
    launch_root.configure(bg="#1E1E1E")
    
    tk.Label(launch_root, text="파일 이름 인식 실패! 클라이언트를 선택하세요", font=("맑은 고딕", 9, "bold"), bg="#1E1E1E", fg="white").pack(pady=15)
    combo = ttk.Combobox(launch_root, values=["미니1", "미니2", "미니3", "미니4"], state="readonly", font=("맑은 고딕", 12), width=15) # 🚀 미니4 추가
    combo.set("미니1")
    combo.pack(pady=5)
    
    def on_start():
        global TARGET_PC_KEY
        TARGET_PC_KEY = combo.get()
        launch_root.destroy()
        
    tk.Button(launch_root, text="독립 엔진 시작", command=on_start, font=("맑은 고딕", 10, "bold"), bg="#4CAF50", fg="white", relief="flat", width=15).pack(pady=10)
    launch_root.mainloop()

run_launcher()

