def save_pos_command():
    entry_gui_x.delete(0, tk.END); entry_gui_x.insert(0, str(root.winfo_x()))
    entry_gui_y.delete(0, tk.END); entry_gui_y.insert(0, str(root.winfo_y()))
    
    import win32gui
    hwnd = win32gui.FindWindow(None, TARGET_PC_TITLE)
    if hwnd:
        rect = win32gui.GetWindowRect(hwnd)
        target_x, target_y = rect[0], rect[1]
        
        style, ex_style = win32gui.GetWindowLong(hwnd, win32con.GWL_STYLE), win32gui.GetWindowLong(hwnd, win32con.GWL_EXSTYLE)
        client_rect = RECT(0, 0, 800, 600)
        ctypes.windll.user32.AdjustWindowRectEx(ctypes.byref(client_rect), style, False, ex_style)
        full_w, full_h = client_rect.right - client_rect.left, client_rect.bottom - client_rect.top
        
        try: pc_idx = int(TARGET_PC_KEY.replace("미니", "")) - 1
        except: pc_idx = 0
        
        if pc_idx == 0: base_x, base_y = target_x, target_y
        elif pc_idx == 1: base_x, base_y = target_x, target_y + full_h
        elif pc_idx == 2: base_x, base_y = target_x - full_w, target_y + full_h
        else: base_x, base_y = target_x - full_w, target_y 
            
        entry_base_x.delete(0, tk.END); entry_base_x.insert(0, str(base_x))
        entry_base_y.delete(0, tk.END); entry_base_y.insert(0, str(base_y))
        
        global BASE_X, BASE_Y
        BASE_X, BASE_Y = base_x, base_y

    save_settings()
    btn_save_pos.config(text="✅저장", bg="#2E7D32")
    root.after(2000, lambda: btn_save_pos.config(text="📍위치", bg="#455A64"))

