for i, pc in enumerate(MINI_PCS):
    key = pc["key"]
    vars_dict = gui_vars[key]
    
    col_frame = tk.LabelFrame(frame_roles, text=f" 📺 [{key}] 독립 제어 패널 ", font=("맑은 고딕", 11, "bold"), padx=10, pady=10, bg=BG_PANEL, fg="#4FC3F7", bd=1)
    col_frame.grid(row=0, column=0, padx=5, pady=5, sticky="nsew") 
    btn_dict[key] = col_frame
    
    # ---------------------------------------------------------
    # 📌 [항상 고정 - 상단부] 포트 및 FPS 설정 (해제 버튼 추가 버전)
    # ---------------------------------------------------------
    top_panel_frame = tk.Frame(col_frame, bg=BG_PANEL)
    top_panel_frame.pack(side="top", fill="x", pady=(0, 5))

    port_frame = tk.Frame(top_panel_frame, bg=BG_PANEL)
    port_frame.pack(side="top", fill="x", pady=(0, 4))
    tk.Label(port_frame, text="🔌 COM", bg=BG_PANEL, fg="#FFF9C4", font=("맑은 고딕", 9, "bold")).pack(side="left", padx=(0, 2))
    
    import serial.tools.list_ports
    live_ports = []
    for p in serial.tools.list_ports.comports():
        desc = str(p.description).lower()
        hwid = str(p.hwid).lower() if p.hwid else ""
        if "usb" in desc or "serial" in desc or "cp210" in desc or "ch340" in desc or "usb" in hwid:
            live_ports.append(p.device)
            
    # 🚀 추적된 포트가 콤보박스 목록에 없으면 강제 추가 (크래시 버그 방지)
    current_port_val = vars_dict["com_port"].get()
    if current_port_val and current_port_val not in live_ports:
        live_ports.append(current_port_val)
        
    live_ports.sort(key=lambda x: int(x.replace("COM", "")) if x.startswith("COM") and x[3:].isdigit() else 999)
    if not live_ports: live_ports = [current_port_val]
    
    cb_port = ttk.Combobox(port_frame, textvariable=vars_dict["com_port"], values=live_ports, width=6, font=("맑은 고딕", 9, "bold"))
    cb_port.pack(side="left", padx=2)
    
    def make_reconnect_cmd(t_key):
        def cmd():
            port_num = gui_vars[t_key]["com_port"].get().strip()
            if port_num and not port_num.upper().startswith("COM"): port_name = f"COM{port_num}"
            else: port_name = port_num.upper()
            gui_vars[t_key]["com_port"].set(port_name)
            
            with pico_locks[t_key]:
                current_pico = picos.get(t_key)
                
                # 🚀 [핫스왑 1단계] 이미 똑같은 포트에 연결되어 있다면 무시
                if current_pico and getattr(current_pico, 'is_open', False) and current_pico.port.upper() == port_name:
                    print(f"\n✅ [{t_key}] 이미 {port_name} 포트가 정상 연결되어 사용 중입니다! (중복 연결 무시)")
                    return 

                print(f"\n🔄 [{t_key}] {port_name} 포트 실시간 핫스왑 연결 시도 중...")
                
                # 🚀 기존 연결 닫기 (옛날 포트 멱살 놓기)
                if current_pico:
                    try: 
                        current_pico.close()
                        import time
                        time.sleep(0.1) 
                    except: pass
                    
                if port_name:
                    try: 
                        # 💡 BAUD_RATE 전역변수 참조 (115200)
                        baud = globals().get("BAUD_RATE", 115200)
                        # 🚀 [핫스왑 2단계] 포트 즉시 개통!
                        picos[t_key] = serial.Serial(port_name, baud, timeout=0, write_timeout=0)
                        print(f"✅ [{t_key}] -> {port_name} 실시간 연결 및 장착 성공!")
                        
                        # 🚨 [핵심: 멍때림(프리즈) 완벽 소각!]
                        # 옛날 포트가 남겨둔 명령 찌꺼기와 대기 신호를 완전히 부숴버려서 FSM이 갇히지 않게 구출합니다!
                        if t_key in pico_queues:
                            with pico_queues[t_key].mutex:
                                pico_queues[t_key].queue.clear()
                        reset_hw_key_states(picos[t_key])
                        
                        import time
                        if t_key in ai_states:
                            ai_states[t_key]["pico_arrived"] = True
                            ai_states[t_key]["hw_busy"] = False
                            ai_states[t_key]["special_ack_arrived"] = True # ACK 무한대기 족쇄 해제
                            ai_states[t_key]["loot_ack_arrived"] = True
                            ai_states[t_key]["skid_dx"] = 0
                            ai_states[t_key]["skid_dy"] = 0
                            
                            # 👇👇👇 [핵심 수술] 피코가 재부팅(1.5초)할 동안 AI 뇌도 2.5초간 강제 휴식 및 상태 포맷! 👇👇👇
                            ai_states[t_key]["cooldown"] = time.time() + 2.5
                            
                            # 혹시 꼬여있을 FSM도 깔끔하게 초기화하여 무한루프 완벽 차단!
                            if ai_states[t_key].get("is_hunt_active", False):
                                ai_states[t_key]["target_fsm"] = "IDLE"
                                ai_states[t_key]["is_attacking"] = False
                                ai_states[t_key]["is_pulling"] = False
                                ai_states[t_key]["sweep_active"] = False
                                ai_states[t_key]["loot_state"] = "IDLE"
                            # 👆👆👆 ========================================================= 👆👆👆
                        
                        # 🚀 [불변의 지문 즉각 갱신] 파이썬 뇌출혈의 원인이던 'import serial' 문구 원천 삭제 완료! (글로벌 모듈 사용)
                        for p in serial.tools.list_ports.comports():
                            if p.device.upper() == port_name:
                                if t_key not in ai_states: ai_states[t_key] = {}
                                unique_id = str(p.serial_number) if p.serial_number else (str(p.location) if p.location else str(p.hwid))
                                ai_states[t_key]["pico_hwid"] = unique_id
                                print(f"🔒 [{t_key}] 절대 지문({unique_id}) 실시간 갱신 완료!")
                                break
                                
                    except Exception as e:
                        picos[t_key] = None; print(f"⚠️ [{t_key}] {port_name} 연결 실패! ({e})")
                else: 
                    picos[t_key] = None
                    
            # 🚀 [핫스왑 3단계] 연결이 끝나는 즉시, 파일 저장 버튼을 눌러 영구 박제!
            save_settings() 
        return cmd
        
