def auto_arrange_terminal():
    """🚀 터미널(도스창) 자동 최소화 및 빠른 편집 모드 프리징 완벽 차단!"""
    import ctypes
    import win32gui
    import win32con
    import win32api
    
    hwnd = ctypes.windll.kernel32.GetConsoleWindow()
    if hwnd:
        # =================================================================
        # 🚨 [원인 1 완벽 수술] 윈도우 터미널 '빠른 편집 모드' 강제 비활성화!
        # 터미널 창을 실수로 클릭했을 때 파이썬 스레드가 일시정지되고 GUI가 먹통이 되는 윈도우 종특 버그를 원천 차단합니다.
        # =================================================================
        try:
            kernel32 = ctypes.windll.kernel32
            hStdIn = kernel32.GetStdHandle(-10) # STD_INPUT_HANDLE (-10)
            mode = ctypes.c_uint32()
            if kernel32.GetConsoleMode(hStdIn, ctypes.byref(mode)):
                mode.value &= ~0x0040 # ENABLE_QUICK_EDIT_MODE (0x0040) 강제 끄기
                mode.value |= 0x0080  # ENABLE_EXTENDED_FLAGS (0x0080) 필수 플래그 유지
                kernel32.SetConsoleMode(hStdIn, mode)
        except Exception:
            pass

        try:
            # 🚨 [최소화 팩트 체크] 도스창이 이미 최소화(-) 상태인가?
            if win32gui.IsIconic(hwnd):
                return
                
            gui_x = root.winfo_x()
            gui_y = root.winfo_y()
            if gui_x < 0 or gui_y < 0:
                gui_x, gui_y = start_x, start_y
            
            # 🚀 터미널 가로 폭을 800, 세로를 400으로 시원하게 확장!
            term_w, term_h = 800, 400
            screen_w = win32api.GetSystemMetrics(0)
            
            # 🚀 GUI 위치에 덮어씌우되, 우측 화면 밖으로 짤리지 않게 스마트 방어!
            target_x = gui_x
            if target_x + term_w > screen_w:
                target_x = screen_w - term_w
                
            # 🚀 타이틀바가 GUI의 중간쯤(Y + 300) 오도록 배치
            target_y = gui_y + 300
            
            # 🚨 [원인 2 완벽 수술] 억지로 화면에 띄우던 SWP_SHOWWINDOW 옵션 삭제!
            flags = win32con.SWP_NOACTIVATE | win32con.SWP_NOZORDER
            win32gui.SetWindowPos(hwnd, 0, target_x, target_y, term_w, term_h, flags)
            
            # 🚀 [최종 마무으리] 진짜 "최소화" 명령어 발사! (작업표시줄로 즉시 내림)
            win32gui.ShowWindow(hwnd, win32con.SW_MINIMIZE)
            
        except Exception:
            pass

# 프로그램이 켜지고 0.5초 뒤 터미널 창을 제자리로 이동 및 최소화!
root.after(500, auto_arrange_terminal)

def on_closing():
    print("[SYSTEM] 💾 시스템 종료 및 버프 타이머/GUI 설정 저장중...")
    try:
        save_buff_times(ai_states) 
        save_settings() 
    except: pass
    if winmm: 
        try: winmm.timeEndPeriod(1)
        except: pass
    
    # 🚨 [응답 없음 완벽 해결] root.destroy()가 무한 대기(데드락)의 주범이었습니다!
    # 어차피 파일 저장이 끝났으므로, 윈도우 OS가 파이썬 프로세스를 즉각 '강제 자살' 시키도록 핵버튼만 누릅니다!
    print("✅ 안전하게 강제 종료되었습니다.")
    import os
    os._exit(0) 

root.protocol("WM_DELETE_WINDOW", on_closing)
root.mainloop()